{"command": "create", "path": "/tmp/new_extract.py", "file_text": "import os
import re
import pytesseract
from PIL import Image, ImageOps
import openpyxl

IMG_DIR = "/app/workspace/dataset/img"
OUT_PATH = "/app/workspace/stat_ocr.xlsx"

MONTHS = {
    "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
    "jul": 7, "aug": 8, "sep": 9, "sept": 9, "oct": 10, "nov": 11, "dec": 12,
    "january": 1, "february": 2, "march": 3, "april": 4, "june": 6, "july": 7,
    "august": 8, "september": 9, "october": 10, "november": 11, "december": 12,
}

PRIORITY_PATTERNS = [
    (1, re.compile(r"\bGRAND\s*TOTAL\b", re.I)),
    (2, re.compile(r"\bTOTAL\s*:?\s*RM\b", re.I)),
    (3, re.compile(r"\bTOTAL\s+AMOUNT\b", re.I)),
    (4, re.compile(r"\bNETT?\s+TOTAL\b", re.I)),
    (4, re.compile(r"\bBALANCE\s+DUE\b", re.I)),
    (4, re.compile(r"\bAMOUNT\s+DUE\b", re.I)),
    (4, re.compile(r"\bTOTAL\s+DUE\b", re.I)),
    (4, re.compile(r"\bTOTAL\b", re.I)),
    (4, re.compile(r"\bAMOUNT\b", re.I)),
]

EXCLUSION_PATTERNS = [
    re.compile(r"\bSUB[\-\s]?TOTAL\b", re.I),
    re.compile(r"\bTOTAL\s+QTY\b", re.I),
    re.compile(r"\bTOTAL\s+ITEMS?\b", re.I),
    re.compile(r"\bTOT\s*QTY\b", re.I),
    re.compile(r"\bEXCLUDING\b", re.I),
    re.compile(r"\bEXCLUDE\b", re.I),
    re.compile(r"\bEXCL\.?\s+GST\b", re.I),
    re.compile(r"\bTOTAL\s+TAX\b", re.I),
    re.compile(r"\bTOTAL\s+GST\b", re.I),
    re.compile(r"\bTOTAL\s+SST\b", re.I),
    re.compile(r"\bGST\s+PAYABLE\b", re.I),
    re.compile(r"\bGST\s+SUMMARY\b", re.I),
    re.compile(r"^\s*GST\b", re.I),
    re.compile(r"^\s*SST\b", re.I),
    re.compile(r"^\s*TAX\b(?!\s+INVOICE)", re.I),
    re.compile(r"^\s*S\s*[:.]?\s*GST", re.I),
    re.compile(r"\bAMOUNT\s*\(?\s*RM\s*\)?\s*TAX\s*\(?\s*RM\s*\)?", re.I),
    re.compile(r"\bAMT\s*\(?\s*RM\s*\)?\s*TAX\s*\(?\s*RM\s*\)?", re.I),
    re.compile(r"\bNET\s+AMT\b", re.I),
    re.compile(r"\bDISCOUNT\b", re.I),
    re.compile(r"\bCHANGE\b", re.I),
    re.compile(r"\bCASH\s+TENDERED\b", re.I),
    re.compile(r"\bROUNDING\b", re.I),
    re.compile(r"\bROUND\s+ADJ", re.I),
    re.compile(r"\bQTY\s+(S/|U\.?)?PRICE\s+(AMOUNT|TOTAL)\b", re.I),
]

STOP_PATTERNS = [
    re.compile(r"\bGST\s+SUMMARY\b", re.I),
    re.compile(r"\bSST\s+SUMMARY\b", re.I),
    re.compile(r"\bTAX\s+SUMMARY\b", re.I),
]

NUM_RE = re.compile(r"\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2}")


def is_excluded(line: str) -> bool:
    for p in EXCLUSION_PATTERNS:
        if p.search(line):
            return True
    return False


def get_priority(line: str):
    for prio, pat in PRIORITY_PATTERNS:
        if pat.search(line):
            return prio
    return None


def is_stop(line: str) -> bool:
    for p in STOP_PATTERNS:
        if p.search(line):
            return True
    return False


def parse_date(text: str):
    results = []

    for m in re.finditer(r"\b(20\d{2})[-/\.](\d{1,2})[-/\.](\d{1,2})\b", text):
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= mo <= 12 and 1 <= d <= 31:
            results.append(f"{y:04d}-{mo:02d}-{d:02d}")

    for m in re.finditer(r"\b(\d{1,2})[-/\.](\d{1,2})[-/\.](20\d{2})\b", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= mo <= 12 and 1 <= d <= 31:
            results.append(f"{y:04d}-{mo:02d}-{d:02d}")

    for m in re.finditer(r"\b(\d{1,2})[-/\.](\d{1,2})[-/\.](\d{2})\b", text):
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if 1 <= mo <= 12 and 1 <= d <= 31:
            year = 2000 + y if y < 70 else 1900 + y
            results.append(f"{year:04d}-{mo:02d}-{d:02d}")

    for m in re.finditer(r"\b(\d{1,2})\s+([A-Za-z]{3,9})\s+(20\d{2})\b", text):
        d = int(m.group(1))
        mo_name = m.group(2).lower().rstrip(",.")
        if mo_name in MONTHS:
            mo = MONTHS[mo_name]
            y = int(m.group(3))
            if 1 <= d <= 31:
                results.append(f"{y:04d}-{mo:02d}-{d:02d}")

    for m in re.finditer(r"\b([A-Za-z]{3,9})\s+(\d{1,2}),?\s+(20\d{2})\b", text):
        mo_name = m.group(1).lower().rstrip(",.")
        if mo_name in MONTHS:
            mo = MONTHS[mo_name]
            d = int(m.group(2))
            y = int(m.group(3))
            if 1 <= d <= 31:
                results.append(f"{y:04d}-{mo:02d}-{d:02d}")

    if results:
        return results[0]
    return None


def parse_amount(line: str):
    nums = NUM_RE.findall(line)
    if not nums:
        return None
    val = nums[-1].replace(",", "")
    return val


def extract_total(text: str):
    lines = text.splitlines()
    candidates = []
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        if is_stop(line):
            break
        if is_excluded(line):
            continue
        prio = get_priority(line)
        if prio is None:
            continue
        amt = parse_amount(line)
        if amt is None:
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                if not nxt.strip():
                    continue
                if is_stop(nxt) or is_excluded(nxt):
                    break
                amt = parse_amount(nxt)
                break
        if amt is None:
            continue
        candidates.append((prio, i, amt))
    if not candidates:
        return None
    best_prio = min(c[0] for c in candidates)
    top = [c for c in candidates if c[0] == best_prio]
    _, _, amt = top[-1]
    try:
        v = float(amt)
    except ValueError:
        return None
    return f"{v:.2f}"


def ocr_variants(path: str):
    img = Image.open(path).convert("L")
    w, h = img.size
    variants = []
    for scale in [2.0, 1.5, 3.0]:
        scaled = img.resize((int(w * scale), int(h * scale)), Image.LANCZOS)
        for psm in [6, 4, 3, 11]:
            try:
                txt = pytesseract.image_to_string(scaled, config=f"--psm {psm}")
                variants.append((scale, psm, txt))
            except Exception:
                pass
    return variants


def process_file(path: str):
    variants = ocr_variants(path)
    primary = next((v for v in variants if v[0] == 2.0 and v[1] == 6), variants[0])
    primary_text = primary[2]
    date = parse_date(primary_text)
    total = extract_total(primary_text)
    if date is None:
        for _, _, txt in variants:
            date = parse_date(txt)
            if date:
                break
    if total is None:
        for _, _, txt in variants:
            total = extract_total(txt)
            if total:
                break
    return date, total


def main():
    files = sorted(os.listdir(IMG_DIR))
    files = [f for f in files if f.lower().endswith((".jpg", ".jpeg", ".png"))]

    results = []
    for f in files:
        p = os.path.join(IMG_DIR, f)
        date, total = process_file(p)
        results.append((f, date, total))
        print(f"{f}: date={date} total={total}")

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for f, d, t in results:
        ws.append([f, d, t])
    wb.save(OUT_PATH)
    print(f"Saved to {OUT_PATH}")


if __name__ == "__main__":
    main()
"}

